j={'candidate':'MALABAR V12 REBUILD 1','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'Local tested reconstruction frozen; publication approval and new full-game browser/GPU acceptance pending. Not the lost earlier V12 candidate.','runtime_tree_sha256':tree,'tree_algorithm':'SHA256 of sorted relative-path + NUL + file SHA256 + newline','runtime_files':rows,'anchors':{p:{'bytes':(R/p).stat().st_size,'sha256':H(R/p)}for p in anchors},'fresh_gate':'npm test exited 0; build + 89 embedded-asset identity, full Three MIT/font OFL and PNG/native metadata checks pass. See tests/recovery/full_gate.log.','source_test_limits':['No WebGL rendering, live-device handling or audio-listening claim','R2 actual CSS tests use labeled static original Blender images; final seven-car R3 CSS public review pending authorization','Paid cars use earned local coins, not real money; this profile is not trusted online ownership'],'license_correction':'Approved forward-only original-asset wording correction; genuine OSM/Three/font/dependency notices preserved; no history rewrite/revocation claim.'}
(R/'tests/release/V12_REBUILD_RELEASE.json').write_text(json.dumps(j,indent=2)+'\n');print(json.dumps({'runtime_tree_sha256':tree,'runtime_files':len(rows),'standalone':j['anchors']['dist/malabar-hot-coast.html']},indent=2))
